test('adjustStock races with reserve, commit and release without breaking the counters', async () => {
  const svc = await service({ widget: 20 });
  const jobs = [];
  let committed = 0;
  for (let i = 0; i < 20; i++) {
    jobs.push((async () => {
      try {
        await svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }]);
      } catch (err) {
        if (!(err instanceof InsufficientStockError)) throw err;
        return;
      }
      if (i % 2) {
        await svc.commit(`o${i}`);
        committed++;
      } else await svc.release(`o${i}`);
    })());
    jobs.push(svc.adjustStock('widget', -1, 'shrink').catch(err => {
      if (!(err instanceof InsufficientStockError)) throw err;
    }));
    jobs.push(svc.adjustStock('widget', 1, 'found'));
  }
  await Promise.all(jobs);
  const { stock, reserved, sold } = await svc.snapshot('widget');
  assert.equal(reserved, 0);
  assert.equal(sold, committed);
  assert.equal(stock, 20 - committed, 'every shrink was matched by a found');
});
